# quick sanity: min interatomic distances
import numpy as np
lines = open('init.xyz').read().split('\n')[2:]
els=[]; xyz=[]
for l in lines:
    p=l.split()
    if len(p)==4:
        els.append(p[0]); xyz.append([float(x) for x in p[1:]])
xyz=np.array(xyz)
n=len(els)
mind=99
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if d<mind: mind=d; pair=(i,j,els[i],els[j])
print("min dist", mind, pair)
# check Zr-O, Zr-Cl
for i,e in enumerate(els):
    if e in ('O','Cl'):
        print(e, i, round(np.linalg.norm(xyz[i]-xyz[0]),2))
EOF
